import { useEffect, useState } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, PAGE_SIZE, pageCount, type ThreadSummary } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-02 no existe cuando se escribió MSG-01: abrir un hilo no navega a ningún
 * sitio. `onOpenThread` se declara en la firma —la pasa el shell desde App.tsx,
 * F-118— y se ignora a propósito.
 */
const noop = () => undefined;

/**
 * Texto real del fallo para el aviso de error (F-128).
 *
 * PostgREST rechaza con un objeto plano `{ code, message }`, así que ni
 * `String(e)` (da `[object Object]`) ni `e.message` (da `undefined`) sirven.
 * Se sacan `code` y `message` cuando existen y se pintan junto a la frase
 * para humanos.
 */
function errorText(e: unknown): string {
  if (e instanceof Error) return e.message || 'Error desconocido';
  if (typeof e === 'object' && e !== null) {
    const obj = e as { code?: unknown; message?: unknown };
    if (typeof obj.code === 'string' && obj.code.length > 0) {
      return typeof obj.message === 'string' && obj.message.length > 0
        ? `${obj.code}: ${obj.message}`
        : obj.code;
    }
    if (typeof obj.message === 'string' && obj.message.length > 0) return obj.message;
  }
  return String(e);
}

/**
 * MSG-01 · Lista de Hilos.
 *
 * Es la pantalla, no un componente de presentación: posee el estado de
 * búsqueda y de página, y llama a `fetchThreadPage` con `profile.orgId`.
 * El orden de las filas lo decide el servidor (`last_item_at` descendente).
 */
export function Messages({
  profile,
  now,
}: {
  profile: MemberProfile;
  now?: Date;
  onOpenThread?: (threadId: string) => void;
}) {
  const [draft, setDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const resolvedNow = now ?? new Date();

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(errorText(e));
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  const pages = pageCount(total, PAGE_SIZE);
  const pageNumbers = Array.from({ length: pages }, (_, i) => i + 1);

  return (
    <>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      {/* El MVP no tiene passphrase: las claves viven en memoria de sesión.
          No hay botón "Introducir frase de seguridad" porque no es una acción
          disponible (CLAUDE.md §4; Plan §9 "Fuera"). */}
      <div className={styles.e2eeBar}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves en memoria de sesión · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                setPage(1);
                setSearch(draft);
              }
            }}
          />
        </div>
        {/* "Nuevo contacto" abre DIR-01, que no está en el alcance del MVP:
            se pinta deshabilitado con el motivo, como el botón de subida de
            INV-01 (F-023 e). */}
        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          title="El Directorio queda fuera del MVP"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.threadCount}>
          {total.toLocaleString('es-ES')} {total === 1 ? 'hilo' : 'hilos'} · Página{' '}
          {page.toLocaleString('es-ES')} de {pages.toLocaleString('es-ES')}
        </span>
      </div>

      {error ? (
        // F-127: el aviso de error lleva role="alert", no es un div cualquiera.
        <div className={styles.error} role="alert">
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {error}</span>
        </div>
      ) : loading ? (
        <div className={styles.loading}>Cargando hilos...</div>
      ) : (
        <ThreadList threads={threads} now={resolvedNow} onOpen={noop} />
      )}

      {total > 0 && !error && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={styles.pageBtn}
            disabled={page === 1}
            aria-label="Página anterior"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            ‹
          </button>
          {pageNumbers.map((n) => (
            <button
              key={n}
              type="button"
              className={`${styles.pageBtn} ${n === page ? styles.pageActive : ''}`}
              aria-current={n === page ? 'page' : undefined}
              onClick={() => setPage(n)}
            >
              {n}
            </button>
          ))}
          <button
            type="button"
            className={styles.pageBtn}
            disabled={page === pages}
            aria-label="Página siguiente"
            onClick={() => setPage((p) => Math.min(pages, p + 1))}
          >
            ›
          </button>
        </div>
      )}
    </>
  );
}

