/* Lista de hilos de MSG-01.
   Todo color sale de las variables del sistema (design-system §1):
   ningún hex, ningún rgb() literal. */

.listHeader {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  padding: 6px 18px;
  background: var(--bw-surface-mist); /* el mock usa blanco puro, que no es token */
  border: 1px solid var(--bw-line-steel);
  border-bottom: none;
  border-radius: 8px 8px 0 0;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-input-placeholder);
}

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-surface-mist); /* el mock usa blanco puro, que no es token */
  border: 1px solid var(--bw-line-steel);
  border-radius: 0 0 8px 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

/* El botón ES la fila: ocupa todo el <li> y es el elemento pulsable.
   El <li> sigue siendo un listitem sin ningún role encima (F-131). */
.threadBtn {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  color: inherit;
  transition: background 0.1s;
}

.threadBtn:hover {
  background: var(--bw-row-hover-tint);
}

.threadTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  /* El mock usa 14px; el sistema no tiene ese token, se usa --bw-size-body. */
  font-size: var(--bw-size-body);
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.time {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
  justify-self: end;
}

.threadBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-label);
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío ──────────────────────────────────────────────────────── */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 48px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyText {
  font-size: var(--bw-size-body);
  color: var(--bw-deep-steel);
  line-height: 1.6;
  max-width: 460px;
}

.emptyReason {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  line-height: 1.5;
  max-width: 460px;
}

.emptyBtn {
  margin-top: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  /* El mock usa blanco puro; --bw-on-dark-hover es el token más cercano. */
  color: var(--bw-on-dark-hover);
  font-family: inherit;
  font-size: var(--bw-size-input);
  font-weight: 500;
  opacity: 0.55;
  cursor: not-allowed;
}

