import { previewLabel, relativeTime, stateTone, type ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onOpen: (id: string) => void;
}

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas en el orden exacto en que las recibe: el orden es del
 * servidor (`last_item_at` descendente), no una decisión del componente.
 *
 * F-131: cada hilo vive en un `<li>` y ese `<li>` conserva su rol `listitem`;
 * la pulsación la hace un `<button>` DENTRO del `<li>`, y es ese botón el que
 * lleva el nombre accesible del hilo. Un `role="button"` encima del `<li>`
 * sustituiría al `listitem` y rompería el contrato de accesibilidad.
 */
export function ThreadList({ threads, now, onOpen }: Props) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <p className={styles.emptyReason}>
          El Directorio queda fuera del MVP en esta versión, por lo que este botón está deshabilitado.
        </p>
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
      </div>
    );
  }

  return (
    <>
      <div className={styles.listHeader}>
        <span>Empresa</span>
        <span>Estatus</span>
      </div>
      <ul className={styles.list}>
        {threads.map((t) => {
          const tone = stateTone(t.state);
          return (
            <li key={t.id} className={styles.row}>
              <button
                type="button"
                className={styles.threadBtn}
                onClick={() => onOpen(t.id)}
              >
                <span className={styles.threadTop}>
                  <span className={styles.orgName}>{t.counterpartyName}</span>
                  {t.counterpartyCountry ? (
                    <span className={styles.countryBadge}>{t.counterpartyCountry}</span>
                  ) : null}
                </span>
                <time className={styles.time} dateTime={t.lastItemAt}>
                  {relativeTime(t.lastItemAt, now)}
                </time>
                <span className={styles.threadBottom}>
                  <span className={styles.preview}>{previewLabel(t.lastItem)}</span>
                  <span className={`${styles.badge} ${styles[tone]}`}>{t.state}</span>
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </>
  );
}
